cd /workspace && npm install xlsx 2>/dev/null | tail -3; node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/travel_expenses.xlsx');
const ws = wb.Sheets[wb.SheetNames[0]];
const data = XLSX.utils.sheet_to_json(ws);
console.log('Sheet:', wb.SheetNames[0]);
console.log('Rows:', data.length);
console.log('Columns:', Object.keys(data[0]));
console.log();
console.log('=== ALL DATA ===');
console.table(data);
console.log();

// Summarize numeric columns
const numCols = Object.keys(data[0]).filter(k => typeof data[0][k] === 'number');
console.log('=== NUMERIC SUMMARY ===');
for (const col of numCols) {
    const vals = data.map(r => r[col]).filter(v => v != null);
    const sum = vals.reduce((a,b) => a+b, 0);
    const avg = sum / vals.length;
    const min = Math.min(...vals);
    const max = Math.max(...vals);
    console.log(col + ': Total=' + sum.toFixed(2) + ', Avg=' + avg.toFixed(2) + ', Min=' + min.toFixed(2) + ', Max=' + max.toFixed(2));
}

// Group by string columns
const strCols = Object.keys(data[0]).filter(k => typeof data[0][k] === 'string');
console.log();
for (const col of strCols) {
    const unique = [...new Set(data.map(r => r[col]))];
    if (unique.length < 20) {
        console.log('=== BY ' + col.toUpperCase() + ' ===');
        for (const val of unique.sort()) {
            const rows = data.filter(r => r[col] === val);
            for (const nc of numCols) {
                const sum = rows.reduce((a,r) => a + (r[nc]||0), 0);
                console.log('  ' + val + ' -> ' + nc + ': Total=' + sum.toFixed(2) + ', Count=' + rows.length);
            }
        }
        console.log();
    }
}
"

node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/travel_expenses.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);

// Confirmed, active bookings with dates
const active = data.filter(r => r.Status === 'confirmed');

console.log('=== YOUR CONFIRMED BOOKINGS ===');
console.log();

console.log('-- Hotels --');
active.filter(r => r.Type === 'Hotel').forEach(r => {
    console.log('  ' + r['Booking ID'] + ' | ' + r.User + ' | ' + r['Route/Location'] + ' | ' + r.Dates + ' | \$' + r.Amount);
});

console.log();
console.log('-- Car Rentals --');
active.filter(r => r.Type === 'Car Rental').forEach(r => {
    console.log('  ' + r['Booking ID'] + ' | ' + r.User + ' | ' + r['Route/Location'].split('→')[0].trim() + ' | ' + r.Dates + ' | \$' + r.Amount);
});

console.log();
console.log('-- Flights --');
active.filter(r => r.Type === 'Flight').forEach(r => {
    console.log('  ' + r['Booking ID'] + ' | ' + r.User + ' | ' + r['Route/Location'] + ' | \$' + r.Amount);
});

console.log();
console.log('=== ROUTE FREQUENCY (all bookings) ===');
const flights = data.filter(r => r.Type === 'Flight');
const routes = {};
flights.forEach(r => { routes[r['Route/Location']] = (routes[r['Route/Location']]||0) + 1; });
Object.entries(routes).sort((a,b) => b[1]-a[1]).forEach(([r,c]) => console.log('  ' + r + ': ' + c + ' bookings'));

console.log();
console.log('=== FLIGHT PRICE RANGE (non-zero) ===');
const prices = flights.map(r => r.Amount).filter(a => a > 0).sort((a,b) => a-b);
console.log('  Prices: ' + prices.map(p => '\$'+p).join(', '));
console.log('  Range: \$' + prices[0] + ' - \$' + prices[prices.length-1]);
console.log('  Median: \$' + prices[Math.floor(prices.length/2)]);
"

